// Monta o envio de cada lead do lote (sem I/O por item).
// SDRs oficiais vão pela Cloud API da Meta (número de cada SDR); "Diogo IA" vai pela Evolution API.
const cfg = $('Config').first().json;
const PHONE_IDS = {
  'SDR-MARKETING': cfg.phone_id_marketing,
  'SDR-ADVISOR': cfg.phone_id_advisor,
  'SDR-REMARKETING': cfg.phone_id_remarketing,
  'SDR-INBOUND': cfg.phone_id_inbound,
};

function normalizeTelefone(raw) {
  if (raw == null) return '';
  let d = String(raw).replace(/\D/g, '').replace(/^0+/, '');
  if (!d) return '';
  if (d.startsWith('55')) d = d.slice(2);
  if (d.length === 10 && ['6', '7', '8', '9'].includes(d[2])) d = d.slice(0, 2) + '9' + d.slice(2);
  return '55' + d;
}

return $input.all().map(({ json: l }) => {
  const telefone = normalizeTelefone(l.telefone);
  const evolution = l.origem_disparo === 'Diogo IA';
  const phoneId = PHONE_IDS[l.origem_disparo];
  const tipoMidia = String(l.tipo_midia ?? '').toLowerCase().trim();
  const params = [l.param_1, l.param_2, l.param_3, l.param_4, l.param_5]
    .map((v) => String(v ?? '').trim())
    .filter((t) => t !== '')
    .map((text) => ({ type: 'text', text }));
  const components = [{ type: 'body', parameters: params }];
  const comImagem = tipoMidia === 'imagem' && !!l.imagem_url;
  if (comImagem) {
    components.unshift({ type: 'header', parameters: [{ type: 'image', image: { link: l.imagem_url } }] });
  }
  const mensagem = l.mensagem_completa ?? '';
  return { json: {
    canal: evolution ? 'evolution' : 'meta',
    id: l.id,
    id_disparo: l.id_disparo,
    nome: l.nome,
    telefone,
    origem: l.origem_disparo,
    nome_app: evolution ? 'SDR-DIOGO' : l.origem_disparo,
    tipo_midia: tipoMidia,
    imagem_url: l.imagem_url,
    mensagem,
    // Telefone inválido, ou SDR oficial sem número da Meta/template: o erro registrado é o nosso.
    invalido: !telefone || telefone.length < 12 || (!evolution && (!phoneId || !l.template_name)),
    mensagem_historico: l.origem_disparo === 'SDR-MARKETING' && comImagem ? `${l.imagem_url}\n\n${mensagem}` : mensagem,
    url: `https://graph.facebook.com/v22.0/${phoneId}/messages`,
    meta_body: {
      messaging_product: 'whatsapp',
      to: telefone,
      type: 'template',
      template: { name: l.template_name, language: { code: 'pt_BR' }, components },
    },
  }};
});

// Run Once for Each Item: converte a resposta da Meta no formato do registrar_envios_whatsapp.
// Falha transitória (rate limit / 5xx / timeout) volta para a fila; o resto vira 'erro'.
const RETRY_CODES = [4, 80007, 130429, 131000, 131016, 131048, 133004];
const l = $('Loop Meta').item.json;
const r = $json;
const status = Number(r.statusCode ?? 0);
const body = r.body ?? r;
const wamid = body?.messages?.[0]?.id ?? null;
// Lead inválido também passa pela Meta (que rejeita), mas o erro registrado é o nosso.
const ok = !l.invalido && status >= 200 && status < 300 && !!wamid;
const code = Number(body?.error?.code ?? 0);
const retry = !ok && !l.invalido && (status === 0 || status === 429 || status >= 500 || RETRY_CODES.includes(code));
const erro = ok ? null
  : l.invalido ? 'Telefone inválido, origem sem número da Meta ou disparo sem template'
  : body?.error ? `[${code}] ${body.error.message ?? ''} ${body.error.error_data?.details ?? ''}`.trim()
  : (r.error?.message ?? `HTTP ${status}`);
return { json: { id: l.id, id_disparo: l.id_disparo, origem: l.origem, telefone: l.telefone, nome: l.nome,
  nome_app: l.nome_app, mensagem: l.mensagem_historico, ok, retry, wamid, erro } };

// A Evolution recebe a mídia em base64: baixa UMA vez por lote, com timeout.
function stripBOM(buf) { return (buf.length >= 3 && buf[0] === 0xEF && buf[1] === 0xBB && buf[2] === 0xBF) ? buf.slice(3) : buf; }
function fixPngSignature(buf) {
  if (buf.length >= 7 && buf[0] === 0x50 && buf[1] === 0x4E && buf[2] === 0x47 && buf[3] === 0x0D && buf[4] === 0x0A && buf[5] === 0x1A && buf[6] === 0x0A) {
    return Buffer.concat([Buffer.from([0x89]), buf]);
  }
  return buf;
}

const items = $input.all();
const first = items[0]?.json || {};
const url = String(first.imagem_url || '').trim();
let base64 = '';
let mime = '';
if (url && ['imagem', 'video'].includes(first.tipo_midia)) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url, headers: { 'User-Agent': 'Mozilla/5.0' },
      responseFormat: 'arraybuffer', returnFullResponse: true, timeout: 20000,
    });
    let buf = stripBOM(Buffer.from(res.body ?? res.data ?? res));
    mime = (res.headers?.['content-type'] || '').split(';')[0].trim();
    const isPng = mime.includes('png') || (buf.length >= 3 && buf[0] === 0x50 && buf[1] === 0x4E && buf[2] === 0x47);
    if (first.tipo_midia === 'imagem' && isPng) buf = fixPngSignature(buf);
    base64 = buf.toString('base64');
  } catch (e) {
    base64 = '';
  }
}
return items.map(({ json }) => ({ json: { ...json, base64, mime } }));

// Run Once for Each Item: converte a resposta da Evolution no formato do registrar_envios_whatsapp.
const l = $('Loop Evolution').item.json;
const r = $json;
const wamid = r?.key?.id ?? null;
const ok = !l.invalido && !!wamid;
const msgErro = String(r?.error?.message ?? r?.error ?? r?.message ?? '');
const erro = ok ? null : (l.invalido ? 'Telefone inválido' : (msgErro || 'Evolution não retornou o id da mensagem'));
// Só falha de rede volta para a fila; erro de número/instância não adianta repetir.
const retry = !ok && !l.invalido && /timeout|ECONN|ETIMEDOUT|socket hang up/i.test(msgErro);
return { json: { id: l.id, id_disparo: l.id_disparo, origem: l.origem, telefone: '+' + l.telefone, nome: l.nome,
  nome_app: l.nome_app, mensagem: l.mensagem, ok, retry, wamid, erro } };

